class Solution {
    fun groupThePeople(groupSizes:IntArray):List<List<Int>>{
        val pending=mutableMapOf<Int,MutableList<Int>>();
        val answer=mutableListOf<List<Int>>();
        for(person in groupSizes.indices){
            val size=groupSizes[person];
            val group=pending.getOrPut(size){
                mutableListOf()
            };
            group.add(person);
            if(group.size==size){
                answer.add(group);
                pending.remove(size)
            }
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: vector<vector<int>> groupThePeople(vector<int>& groupSizes){
        unordered_map<int,vector<int>> pending;
        vector<vector<int>> answer;
        for(int person=0;person<(int)groupSizes.size();++person){
            int size=groupSizes[person];
            auto& group=pending[size];
            group.push_back(person);
            if((int)group.size()==size){
                answer.push_back(group);
                pending.erase(size);
            }
        }
        return answer;
    }
};
